#!/usr/bin/env node
// Generates the CSS custom properties and @font-face files from design/tokens.json (the single
// source of truth) for the extension (design/) and the website (site/). Run with --check to fail
// when any generated file is out of date.
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadTokens, resolve, root, walk } from './design-tokens-lib.mjs';

const tokens = loadTokens();
const ref = (value) => {
  const match = typeof value === 'string' && value.match(/^\{semantic\.(.+)\}$/);
  return match ? `var(--ie-${match[1]})` : null;
};

function cssValue(token, mode) {
  const { $type: type, $value: raw } = token;
  if (type === 'fontFamily') return raw.map((f) => (/\s/.test(f) && !f.includes('-apple') ? `"${f}"` : f)).join(', ');
  if (type === 'cubicBezier') return `cubic-bezier(${raw.join(', ')})`;
  if (type === 'shadow') {
    const color = ref(raw.color) ?? resolve(tokens, raw.color, mode);
    return `${raw.offsetX} ${raw.offsetY} ${raw.blur} ${raw.spread} ${color}`;
  }
  return String(resolve(tokens, raw, mode));
}

function primitiveName(path) {
  // primitive.color.calco.600 -> calco-600 ; primitive.fs.sm -> fs-sm
  const [, group, ...rest] = path;
  return group === 'color' ? rest.join('-') : [group, ...rest].join('-');
}

function block(entries) {
  return entries.map(([name, value, note]) => `  --ie-${name}: ${value};${note ? ` /* ${note} */` : ''}`).join('\n');
}

const primitives = [...walk(tokens.primitive, ['primitive'])].map(([path, t]) => [primitiveName(path), cssValue(t), t.$description]);
const modeEntries = (mode) => [...walk(tokens.semantic[mode])].map(([path, t]) => [path.join('-'), cssValue(t, mode), mode === 'light' ? t.$description : undefined]);
const shadows = [...walk(tokens.semantic.shadow)].map(([path, t]) => [`shadow-${path.join('-')}`, cssValue(t), t.$description]);

const css = `/* =====================================================================
   Invoice Extractor — design tokens (system "Calco")
   GENERATED from design/tokens.json by scripts/build-design-tokens.mjs.
   Do not edit by hand: edit tokens.json and run the script.
   Light and dark follow the OS; [data-theme] on <html> forces one.
   ===================================================================== */

:root {
${block(primitives)}

  /* ---- Semantic (light) ---- */
${block(modeEntries('light'))}
${block(shadows)}
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${block(modeEntries('dark')).replace(/^/gm, '  ')}
    color-scheme: dark;
  }
}

:root[data-theme="dark"] {
${block(modeEntries('dark'))}
  color-scheme: dark;
}
`;

const FACES = [
  ['Bricolage Grotesque', 'bricolage-grotesque', '200 800'],
  ['Atkinson Hyperlegible Next', 'atkinson-hyperlegible-next', '200 800'],
  ['JetBrains Mono', 'jetbrains-mono', '100 800'],
];
const LATIN = 'U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD';
const LATIN_EXT = 'U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF';
const fontsCss = (dir) => `/* Bundled OFL fonts (licenses in fonts/). GENERATED by scripts/build-design-tokens.mjs. */\n` +
  FACES.flatMap(([family, file, weight]) => [['latin', LATIN], ['latin-ext', LATIN_EXT]].map(([subset, range]) =>
    `@font-face {\n  font-family: "${family}";\n  font-style: normal;\n  font-weight: ${weight};\n  font-display: swap;\n  src: url("${dir}${file}-${subset}.woff2") format("woff2");\n  unicode-range: ${range};\n}`)).join('\n') + '\n';

const outputs = new Map([
  ['design/tokens.css', css],
  ['site/tokens.css', css],
  ['design/fonts.css', fontsCss('../fonts/')],
  ['site/fonts.css', fontsCss('fonts/')],
]);
for (const file of readdirSync(join(root, 'fonts'))) outputs.set(`site/fonts/${file}`, readFileSync(join(root, 'fonts', file)));

const check = process.argv.includes('--check');
const stale = [];
for (const [rel, content] of outputs) {
  const target = join(root, rel);
  const current = existsSync(target) ? readFileSync(target) : null;
  const same = current && Buffer.compare(current, Buffer.from(content)) === 0;
  if (same) continue;
  if (check) { stale.push(rel); continue; }
  mkdirSync(join(target, '..'), { recursive: true });
  if (Buffer.isBuffer(content)) copyFileSync(join(root, 'fonts', rel.split('/').pop()), target);
  else writeFileSync(target, content);
}
if (check && stale.length) {
  console.error(`Design tokens out of date: ${stale.join(', ')}. Run: node scripts/build-design-tokens.mjs`);
  process.exit(1);
}
console.log(check ? 'Design tokens up to date' : 'Built design tokens from design/tokens.json');
